 void CheckpointNorthRamp(Node3D n){float y=(float)(game.World.Height(CheckpointX,ExpeditionCheckpoint.Z-36)-checkpointFloor);Vector3 a=new(-1.5f,0,-20),b=new(1.5f,0,-20),c=new(1.5f,y,-36),d=new(-1.5f,y,-36);var st=new SurfaceTool();st.Begin(Mesh.PrimitiveType.Triangles);foreach(var p in new[]{a,c,b,a,d,c})st.AddVertex(p);st.GenerateNormals();n.AddChild(new MeshInstance3D{Mesh=st.Commit(),MaterialOverride=Textured(new(.40f,.36f,.27f),0,.5f)});PhysicsObstacle(n,new ConvexPolygonShape3D{Points=new[]{a,b,c,d,a+Vector3.Down*.18f,b+Vector3.Down*.18f,c+Vector3.Down*.18f,d+Vector3.Down*.18f}},Vector3.Zero);}
