 void CheckpointGuardArt(Node3D root,string id){HumanCharacter(root,1,0,true);root.Scale=new(.87f,.98f,.9f);int index=id.EndsWith("/1")?1:id.EndsWith("/2")?2:0;Bevel(root.GetNode<Node3D>("Torso"),new(0,.23f,-.21f),new(.32f,.12f,.04f),index==0?new(.32f,.38f,.41f):new(.38f,.34f,.25f));var gun=new Node3D{Name="CheckpointWeapon",Position=new(.13f,.37f,-.34f),RotationDegrees=new(-45,0,0),Scale=new(.6f,.6f,.6f)};root.GetNode<Node3D>("Torso").AddChild(gun);ItemWeapon(gun,index==2?0:1,false);var ration=new Node3D{Name="CarriedRation"};root.GetNode<Node3D>("LeftArm/Elbow/Hand").AddChild(ration);Tube(ration,Vector3.Zero,new(0,-.18f,0),.07f,Steel);ration.Visible=false;root.AddChild(new Label3D{Name="GuardCue",Position=new(0,2.05f,0),FontSize=22,PixelSize=.006f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled,Modulate=new(.82f,.75f,.56f)});}
 void CheckpointPose(Infected e){if(e.Visual.GetChildCount()==0)return;PoseFigure(e.Visual,(float)game.Clock*5,e.Body.Velocity.LengthSquared()>.1?1:0,false);bool aiming=e.AttackState=="guard-aim";e.Visual.GetNode<Node3D>("Torso/CheckpointWeapon").RotationDegrees=new(aiming||Checkpoint.Robbery==1&&e.Id.EndsWith("/0")?0:-45,0,0);if(aiming||Checkpoint.Robbery==1&&e.Id.EndsWith("/0")){e.Visual.GetNode<Node3D>("RightArm").RotationDegrees=new(100,0,-8);e.Visual.GetNode<Node3D>("RightArm/Elbow").RotationDegrees=new(-35,0,0);}else e.Visual.GetNode<Node3D>("Torso").RotationDegrees=new(6,0,0);var cue=e.Visual.GetNode<Label3D>("GuardCue");cue.Text=aiming?"AIMING / TAKE COVER":Checkpoint.Hostile?"CHECKPOINT GUARD":Checkpoint.Revealed?(e.Id.EndsWith("/0")?"RAE":e.Id.EndsWith("/1")?"TOM":"IVES"):"EXHAUSTED SURVIVOR";cue.Modulate=aiming?new(1,.45f,.3f):new(.82f,.75f,.56f);e.Visual.GetNode<Node3D>("LeftArm/Elbow/Hand/CarriedRation").Visible=!Checkpoint.Hostile&&e.Id.EndsWith("/1")&&Checkpoint.DeliveryClock<9;}
 readonly System.Collections.Generic.Dictionary<string,string> checkpointAttackCues=new();
 void DrawCheckpoint(){EnsureCheckpointUi();if(!CheckpointEnabled){checkpointLayer.Visible=false;return;}bool near=dungeon==null&&Distance(player.Position,Ground(CheckpointX,ExpeditionCheckpoint.Z))<85;checkpointLayer.Visible=near&&!paused;checkpointCaption.Text=Checkpoint.LineTime>0?Checkpoint.Line:"";checkpointObjective.Text=!Checkpoint.Revealed&&!Checkpoint.Hostile&&Checkpoint.Watch>0?$"WATCH THE CHECKPOINT / {Math.Min(12,Checkpoint.Watch):0} / 12s":"";
  if(CoopClient){foreach(var e in infected.Where(e=>IsCheckpointGuard(e.Id))){checkpointAttackCues.TryGetValue(e.Id,out var previous);if(previous=="guard-aim"&&e.AttackState==""&&e.Stagger<=0&&Checkpoint.Hostile){CheckpointGunshot(e.Body.Position+Vector3.Up*1.35f);CommunityTracer(e.Body.Position+Vector3.Up*1.35f,e.BossAim);}checkpointAttackCues[e.Id]=e.AttackState;}}if(!LetterNodeLive(checkpointRoot))return;bool open=Checkpoint.Paid||CheckpointCleared;SetCollisions(checkpointGate,!open);checkpointGate.RotationDegrees=new(0,0,open?83:0);checkpointFood.Visible=Checkpoint.DeliveredOnce||Checkpoint.Donated;checkpointTraveller.Visible=Checkpoint.Robbery>0&&!Checkpoint.Hostile;checkpointTraveller.Position=new(.4f,0,Checkpoint.Robbery==1?18-(float)Math.Min(8,Checkpoint.RobberyTime*2):18);foreach(string side in new[]{"Left","Right"})checkpointTraveller.GetNode<Node3D>(side+"Arm").RotationDegrees=new(135,0,side=="Left"?-15:15);checkpointRoot.GetNode<Node3D>("TravellersPack").Visible=Checkpoint.Robbery==2;
  if(Checkpoint.Robbery==0)checkpointShot=0;if(Checkpoint.Robbery==1&&Checkpoint.RobberyTime>=.8&&checkpointShot<1){CheckpointGunshot(CheckpointPoint(-2,1.4f,5));checkpointShot=1;}if(Checkpoint.Robbery==1&&Checkpoint.RobberyTime>=1.6&&checkpointShot<2){CheckpointGunshot(CheckpointPoint(-2,1.4f,5));checkpointShot=2;}
 }
 void EnsureCheckpointUi(){if(checkpointLayer!=null)return;checkpointLayer=new CanvasLayer{Layer=7};AddChild(checkpointLayer);var size=GetViewport().GetVisibleRect().Size;checkpointCaption=new Label{Position=new(180,size.Y-280),Size=new(size.X-360,120),AutowrapMode=TextServer.AutowrapMode.WordSmart,HorizontalAlignment=HorizontalAlignment.Center,MouseFilter=Control.MouseFilterEnum.Ignore};checkpointCaption.AddThemeFontSizeOverride("font_size",19);checkpointCaption.AddThemeColorOverride("font_shadow_color",Colors.Black);checkpointCaption.AddThemeConstantOverride("shadow_offset_x",2);checkpointCaption.AddThemeConstantOverride("shadow_offset_y",2);checkpointLayer.AddChild(checkpointCaption);checkpointObjective=new Label{Position=new(34,190),Size=new(size.X-68,40),MouseFilter=Control.MouseFilterEnum.Ignore};checkpointObjective.AddThemeFontSizeOverride("font_size",14);checkpointObjective.Modulate=new(.83f,.73f,.49f);checkpointLayer.AddChild(checkpointObjective);}
